-- =============================================================================
-- Iceberg DDL — {{catalog}}.{{schema}}.{{table_name}}
-- Generated by DE Agent
--
-- Data Product Type : {{data_product_type}}
-- Table Type        : {{table_type}}
-- Partition Column  : {{partition_col}}
-- Platform          : Databricks (Unity Catalog)
-- Domain            : {{domain_name}}
-- Tenancy           : {{tenancy_name}}
-- =============================================================================

CREATE TABLE IF NOT EXISTS {{catalog}}.{{schema}}.{{table_name}}
(
    -- ── Business columns (from mapping document)
    {{# each business_columns}}
    {{column_name}}   {{spark_sql_type}}{{#if not_null}} NOT NULL{{/if}}   COMMENT '{{column_description}}',
    {{/each}}

    -- ── SCD2 / Audit columns (NonTransactional_SCD2 only)
    {{# if table_type_is_nontransactional_scd2}}
    eff_start_date    DATE            NOT NULL   COMMENT 'SCD2 effective start date',
    eff_end_date      DATE            NOT NULL   COMMENT 'SCD2 effective end date (open = 3499-12-31)',
    active            STRING          NOT NULL   COMMENT 'SCD2 active flag: 1 = current, 0 = expired',
    dw_lod_tmp        TIMESTAMP       NOT NULL   COMMENT 'Data warehouse load timestamp',
    dw_upd_lod_tmp    TIMESTAMP       NOT NULL   COMMENT 'Data warehouse last update timestamp',
    {{/if}}

    -- ── SCD1 / Audit columns (NonTransactional_SCD1 only — no eff_start/end/active)
    {{# if table_type_is_nontransactional_scd1}}
    dw_lod_tmp        TIMESTAMP       NOT NULL   COMMENT 'Data warehouse load timestamp',
    dw_upd_lod_tmp    TIMESTAMP       NOT NULL   COMMENT 'Data warehouse last update timestamp',
    {{/if}}

    -- ── Transactional audit columns (Transactional only — remove for NonTransactional)
    {{# if table_type_is_transactional}}
    dw_bus_dt         DATE            NOT NULL   COMMENT 'Business date partition key',
    dw_lod_tmp        TIMESTAMP       NOT NULL   COMMENT 'Data warehouse load timestamp',
    {{/if}}

    -- ── Row hash (optional — include if change detection uses hash comparison)
    -- dw_row_hash    STRING                     COMMENT 'MD5/SHA2 row hash for change detection'
)
USING iceberg
PARTITIONED BY ({{partition_col}})
COMMENT '{{table_description}}';
